`]})]}),e.jsxs(r,{title:"Why language models read subwords",children:[e.jsxs(t.p,{children:["A tokenizer replaces text with token IDs, each of which selects one row of the embedding table, and decoding maps generated IDs back to text. Training, attention, optimization and scaling all operate on the token sequence that comes out. The course tokenizer of Week 1 is called Monad. PleIAs released it with 8,192 vocabulary entries ",e.jsx(n,{id:"monad-2025",children:"PleIAs, 2025"}),", the size Week 1 gave."]}),e.jsx(t.p,{children:"Cut three ways, the sentence gives these pieces and IDs:"}),e.jsx(t.figure,{"data-rehype-pretty-code-figure":"",children:e.jsx(t.pre,{tabIndex:"0","data-language":"plaintext","data-theme":"github-dark-default github-light-default",children:e.jsxs(t.code,{"data-language":"plaintext","data-theme":"github-dark-default github-light-default",style:{display:"grid"},children:[e.jsx(t.span,{"data-line":"",children:e.jsx(t.span,{children:'"The transformer architecture revolutionized natural language processing."'})}),`
